//! Compact in-game command reference and searchable command catalogue.
#[derive(Clone,Copy)]pub struct HelpEntry{pub command:&'static str,pub category:&'static str,pub summary:&'static str}
pub const ENTRIES:&[HelpEntry]=&[
 HelpEntry{command:"pos1/pos2",category:"selection",summary:"mark selection points"},HelpEntry{command:"sel",category:"selection",summary:"choose one of nine selectors"},HelpEntry{command:"expand/contract/shift/inset/outset",category:"selection",summary:"mutate the active region"},HelpEntry{command:"size/center/count/distr",category:"selection",summary:"inspect selection contents"},
 HelpEntry{command:"set/replace",category:"region",summary:"pattern and mask block edits"},HelpEntry{command:"walls/faces/overlay/hollow",category:"region",summary:"edit region boundaries"},HelpEntry{command:"move/stack",category:"region",summary:"translate or repeat contents"},HelpEntry{command:"smooth/erode/dilate",category:"region",summary:"terrain morphology"},HelpEntry{command:"gravity/naturalize/drain/green/snow/thaw",category:"terrain",summary:"terrain utilities"},HelpEntry{command:"deform",category:"region",summary:"expression coordinate remapping"},
 HelpEntry{command:"sphere/cylinder/pyramid/cone/torus/line",category:"generation",summary:"solid and hollow shape generation"},HelpEntry{command:"layers/scatter/flood/removenear",category:"generation",summary:"layered, scattered and connected edits"},
 HelpEntry{command:"copy/cut/paste/rotate/flip",category:"clipboard",summary:"clipboard operations"},HelpEntry{command:"schemsave/schemload/schemlist",category:"clipboard",summary:"persistent schematics"},
 HelpEntry{command:"undo/redo/clearhistory",category:"history",summary:"edit history"},HelpEntry{command:"setbiome/biomedistr",category:"biome",summary:"paint and inspect biomes"},
 HelpEntry{command:"brush/brushset/brushuse/brushinfo/brushlist",category:"brush",summary:"46-brush catalogue"},HelpEntry{command:"gmask/gpattern",category:"session",summary:"session-wide filters"},HelpEntry{command:"transform*",category:"session",summary:"composable edit transforms"},HelpEntry{command:"limit/timeout/fast/tips/watchdog/session",category:"session",summary:"session configuration"},HelpEntry{command:"calc",category:"utility",summary:"evaluate FAWE expressions"},
];
pub fn search(query:&str)->Vec<HelpEntry>{let q=query.trim().to_ascii_lowercase();ENTRIES.iter().copied().filter(|e|q.is_empty()||e.command.contains(&q)||e.category.contains(&q)||e.summary.contains(&q)).collect()}
pub fn page(number:usize,per_page:usize)->(usize,Vec<HelpEntry>){let pages=ENTRIES.len().div_ceil(per_page.max(1));let p=number.clamp(1,pages.max(1));let start=(p-1)*per_page; (pages,ENTRIES.iter().skip(start).take(per_page).copied().collect())}
#[cfg(test)]mod tests{use super::*;#[test]fn pages_and_search_are_stable(){let(pages,first)=page(1,5);assert!(pages>=4);assert_eq!(first.len(),5);assert!(search("clipboard").iter().all(|e|e.category=="clipboard"||e.summary.contains("clipboard")));assert!(search("does-not-exist").is_empty());}}
